#!/bin/bash
# qchem-6.1 (qchem 6.1) on zeus:alon_q; generated by `rag-drg servers submit` from servers.yaml
#PBS -N water
#PBS -q alon_q
#PBS -l select=1:ncpus=8:mem=32gb
#PBS -l walltime=24:00:00
#PBS -j oe

WORKDIR="$PBS_O_WORKDIR"
JOBID="${PBS_JOBID%%.*}"
cd "$WORKDIR"

# --- qchem-6.1: absolute paths, no environment modules ---
export QC="/usr/local/qchem6.1"
source /usr/local/qchem/qcenv.sh
QCHEM=/usr/local/qchem6.1/bin/qchem

# --- per-job scratch ---
SCRATCH="/gtmp/$USER/$JOBID"
mkdir -p "$SCRATCH"

# on exit, also after a walltime kill or scancel/qdel/condor_rm (SIGTERM): copy back and clean up
cleanup() {
    cd "$WORKDIR" || true
    rm -rf "$SCRATCH"
}
trap cleanup EXIT
trap 'exit 143' TERM INT

export QCSCRATCH="$SCRATCH"
export QCLOCALSCR="$QCSCRATCH/local"
mkdir -p "$QCLOCALSCR"
cd "$WORKDIR"
"$QCHEM" -nt 8 "water.in" "water.out"
